// For each running experiment, calculate statistical significance
const experiments = $input.all().map(i => i.json);
const results = [];

for (const exp of experiments) {
  const variants = exp.variants || {};
  const variantKeys = Object.keys(variants);

  if (variantKeys.length < 2) continue;

  // Get metrics for each variant
  // NOTE: In production, these counts come from Supabase queries
  // For now, structure the expected format
  const variantData = variantKeys.map(key => ({
    key,
    ...variants[key],
    sent: variants[key].sent || 0,
    opened: variants[key].opened || 0,
    clicked: variants[key].clicked || 0,
    replied: variants[key].replied || 0
  }));

  // Calculate rates
  for (const v of variantData) {
    v.open_rate = v.sent > 0 ? v.opened / v.sent : 0;
    v.click_rate = v.sent > 0 ? v.clicked / v.sent : 0;
    v.reply_rate = v.sent > 0 ? v.replied / v.sent : 0;
  }

  // Primary metric for significance test
  const primaryMetric = exp.primary_metric || 'open_rate';

  // Z-test for two proportions (A vs B)
  const a = variantData[0];
  const b = variantData[1];

  const p1 = a[primaryMetric] || 0;
  const p2 = b[primaryMetric] || 0;
  const n1 = a.sent || 0;
  const n2 = b.sent || 0;

  let zScore = 0;
  let pValue = 1;
  let significant = false;
  let winner = null;
  const MIN_SAMPLE = exp.min_sample_size || 100;
  const hasMinSample = n1 >= MIN_SAMPLE && n2 >= MIN_SAMPLE;

  if (hasMinSample && n1 > 0 && n2 > 0) {
    // Pooled proportion
    const pPool = (p1 * n1 + p2 * n2) / (n1 + n2);
    const se = Math.sqrt(pPool * (1 - pPool) * (1/n1 + 1/n2));

    if (se > 0) {
      zScore = (p1 - p2) / se;
      // Approximate p-value from z-score (two-tailed)
      const absZ = Math.abs(zScore);
      pValue = Math.exp(-0.5 * absZ * absZ) / Math.sqrt(2 * Math.PI);
      // Rough two-tailed approximation
      pValue = 2 * pValue;

      significant = pValue < 0.05;

      if (significant) {
        winner = zScore > 0 ? a.key : b.key;
      }
    }
  }

  // Check if experiment should be auto-concluded
  const daysSinceStart = Math.floor(
    (Date.now() - new Date(exp.created_at).getTime()) / (1000 * 60 * 60 * 24)
  );
  const maxDays = exp.max_duration_days || 14;
  const shouldConclude = significant || daysSinceStart >= maxDays;

  results.push({
    experiment_id: exp.id,
    experiment_name: exp.name,
    template_id: exp.template_id,
    cadence_step: exp.cadence_step,
    primary_metric: primaryMetric,
    days_running: daysSinceStart,
    variants: variantData.map(v => ({
      key: v.key,
      sent: v.sent,
      [primaryMetric]: (v[primaryMetric] * 100).toFixed(1) + '%'
    })),
    z_score: zScore.toFixed(3),
    p_value: pValue.toFixed(4),
    significant: significant,
    has_min_sample: hasMinSample,
    winner: winner,
    should_conclude: shouldConclude,
    conclusion_reason: significant ? 'statistical_significance' : 
      (daysSinceStart >= maxDays ? 'max_duration_reached' : 'still_running')
  });
}

console.log(`Evaluated ${results.length} experiments, ${results.filter(r => r.should_conclude).length} ready to conclude`);

return results.map(r => ({ json: r }));

// Conclude experiment: update status and set winner
const exp = $input.first().json;

return [{
  json: {
    id: exp.experiment_id,
    status: 'completed',
    winner: exp.winner || 'no_winner',
    results: {
      variants: exp.variants,
      z_score: exp.z_score,
      p_value: exp.p_value,
      significant: exp.significant,
      conclusion_reason: exp.conclusion_reason,
      concluded_at: new Date().toISOString()
    }
  }
}];
